var i=271;var r=`271-iterative-recipe-improvement`;var a=`262`;var s={en:`Iterative Recipe Improvement`,ua:`Ітеративне вдосконалення рецептів`};var o={short:`Iterative recipe improvement uses measured trials to make a dish better step by step. The goal is not endless adjustment but a controlled process that identifies which changes caused an improvement.`,sections:[{title:`Core idea`,text:`Establish a baseline version and define an objective such as crispness, lower salt, improved appearance, or shorter service time. Change only a limited number of factors per trial.`},{title:`Scientific / practical principles`,text:`Repeated tests reveal trade-offs: higher heat may improve browning but increase overcooking, while more liquid may improve tenderness but dilute flavor. Outcomes need both measurements and structured tasting.`},{title:`How to apply it`,text:`Give each version a code (v1, v2), record the exact change, prepare comparable samples, and score predefined criteria. Keep successful changes, discard failures, and retest combinations only after individual factors are understood.`},{title:`Practical example`,text:`For roasted potatoes, first test parboiling time, then oil quantity, then oven temperature while keeping potato size constant. Record color, exterior crispness, and interior texture.`},{title:`Common mistakes and limitations`,text:`Modifying five variables at once hides causes. A favorite version from one taster may not suit the target audience; safety limits are not variables to relax.`},{title:`Related theories`,text:`261, 266, 270, 272, 275.`},{title:`Hands-on exercise`,text:`Prepare two coded potato-roasting trials while holding potato variety, mass, and cut size constant. Change only the pre-boil duration, photograph both results, compare crispness after five minutes, and log the preferred version with its limitations.`}]};var n={short:`Ітеративне вдосконалення рецепта використовує вимірювані проби для поступового покращення страви. Мета не в нескінченних правках, а у виявленні змін, які справді дали кращий результат.`,sections:[{title:`Головна ідея`,text:`Створіть базову версію й конкретну ціль: хрусткість, менший вміст солі, кращий вигляд або швидшу подачу. За одну спробу змінюйте небагато параметрів.`},{title:`Наукові та практичні принципи`,text:`Тести показують компроміси: вища температура покращує підрум’янення, але може пересушити страву; більше рідини пом’якшує продукт, але розбавляє смак. Потрібні і вимірювання, і дегустація.`},{title:`Як застосовувати`,text:`Позначайте версії як v1, v2 тощо, фіксуйте точні зміни, готуйте порівнювані зразки та оцінюйте за заданими критеріями. Успішні зміни залишайте, невдалі відкидайте.`},{title:`Практичний приклад`,text:`Для печеної картоплі окремо перевірте час попереднього відварювання, кількість олії та температуру духовки. Розмір шматочків залишайте однаковим.`},{title:`Поширені помилки та обмеження`,text:`Одночасна зміна п’яти чинників не показує причини. Смак одного дегустатора не представляє всіх гостей; вимоги безпеки не можна послаблювати заради експерименту.`},{title:`Пов’язані теорії`,text:`261, 266, 270, 272, 275.`},{title:`Практична вправа`,text:`Приготуйте два позначені варіанти запеченої картоплі з однаковими сортом, масою та нарізанням. Змініть лише тривалість попереднього відварювання, сфотографуйте результат, порівняйте хрусткість через п’ять хвилин і запишіть переваги та обмеження кожної версії.`}]};var c=[261,266,270,272,275];var l=`Sources / Джерела`;var d=[`https://www.kingarthurbaking.com/learn`,`https://www.cacfp.org/2024/07/02/recipe-standardization-guide/`,`https://www.kingarthurbaking.com/recipes/resources/recipe-success-guide`];var p={id:271,slug:r,group:`262`,title:s,en:o,ua:n,related:c,referenceTitle:l,references:d};export{p as default,o as en,a as group,i as id,l as referenceTitle,d as references,c as related,r as slug,s as title,n as ua};